  TafSetup("taf/{taf}/setup", "taf.section.setup", null),
  TafSetupStartsWhen("taf/{taf}/setup/starts-when", "setup.starts_when", "manages"),
  TafSetupResultsGoTo("taf/{taf}/setup/results-go-to", "setup.results_go_to", "manages"),
  TafSetupVersions("taf/{taf}/setup/versions", "version.title", "manages"),
  TafWorkflow("taf/{taf}/workflow", "taf.workflow.title", null),
  TafMemory("taf/{taf}/memory", "taf.memory.title", null),
  TafHalt("taf/{taf}/halt", "taf.halt.title", "manages"),
  TafShare("taf/{taf}/share", "people.share.title", "manages");

  /** The values this route takes, in order. */
  val parameters: List<String> get() = pattern.split("/").filter { it.startsWith("{") }.map { it.drop(1).dropLast(1) }

  companion object {
    /** The route a path names, and its values: `taf/3f2a/setup/versions` is [TafSetupVersions],
